-- gen617: 27 zone cambiate, 55 tessere
-- cf97cfd7ced5c37f3d7d468d9486d5bb (988312) → f96ad21282fa8f09b48696aa3f0ba5a9 (997686)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = 'f96ad21282fa8f09b48696aa3f0ba5a9' as combacia
from kv_store where key like 'tmp:gen617:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen617:p%')
where key='app:jsx:src'
  and md5(value) = 'cf97cfd7ced5c37f3d7d468d9486d5bb'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen617:p%') = 'f96ad21282fa8f09b48696aa3f0ba5a9';

update kv_store set value = '{"len":997686,"ver":"gen-6.17"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = 'f96ad21282fa8f09b48696aa3f0ba5a9';

delete from kv_store where key like 'tmp:gen617:p%';
